create schema s7;
create table s7.t (id int primary key, a int, b text, c jsonb) with (fillfactor = 90, toast.autovacuum_enabled = false);
alter table s7.t alter column a set statistics 300;
alter table s7.t alter column b set (n_distinct = -0.5);
alter table s7.t alter column c set storage external;
create index t_lower_b on s7.t (lower(b));
alter index s7.t_lower_b alter column 1 set statistics 400;
create function s7.trg() returns trigger language plpgsql as $$ begin return new; end $$;
create trigger t_always before update on s7.t for each row execute function s7.trg();
alter table s7.t enable always trigger t_always;
create trigger t_replica before insert on s7.t for each row execute function s7.trg();
alter table s7.t enable replica trigger t_replica;
create table s7.p (a int, b text) partition by list (a);
create table s7.p1 partition of s7.p for values in (1);
create index p_lb on s7.p (lower(b), a);
alter index s7.p_lb alter column 1 set statistics 200;
create materialized view s7.mv as select id, b from s7.t;
create index mv_lb on s7.mv (lower(b));
alter index s7.mv_lb alter column 1 set statistics 50;
